record.field:
Bucket = env["account.payment.request.expense.bucket"]
Payment = env["account.payment.request"]

payments = Payment.search([
    ("expense_bucket", "!=", False),
    ("expense_bucket_id", "=", False),
])

for payment in payments:
    bucket = Bucket.search([
        ("code", "=", payment.expense_bucket),
    ], limit=1)

    if bucket:
        payment.write({
            "expense_bucket_id": bucket.id,
        })
